window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ac6a64e782d9cd2d"]={"versions": [{"id": "FIG-ac6a64e782d9cd2d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Aktivitätsdiagramm (Methodology Activity) im Kontext der AUTOSAR-Systemkonfiguration (Methodology). Das Diagramm spezifiziert die Aktivität „Define System Topology“ innerhalb der Entwurfsphase für die Systemtopologie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Kardinalität <code>1</code>): Ausführende Instanz (<code>«performs»</code>).\n</li></ul>\n</li><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Define System Topology</code>: Zentrale Methodik-Aktivität (dargestellt als Prozessbaustein/Aktivitäts-Symbol).\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>ECU Resources Description</code> (Kardinalität <code>1..*</code>): Eingangsartefakt mit Stereotyp <code>«input»</code>.\n</li><li><code>Topology</code> (Kardinalität <code>1</code>): Ausgangsartefakt mit Stereotyp <code>«output»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>System Engineer</code> initiiert und führt die Aktivität <code>Define System Topology</code> aus.\n</li><li>Als Eingabe werden mindestens eine oder mehrere Instanzen von <code>ECU Resources Description</code> (<code>1..*</code>) konsumiert.\n</li><li>Die Aktivität erzeugt als Ergebnis genau eine Systemtopologie-Beschreibung (<code>Topology</code>, Kardinalität <code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Definition der Systemtopologie setzt das Vorliegen der ECU-Ressourcenbeschreibungen voraus, um Netzwerkcluster, Steuergeräte und Busverbindungen festzulegen. Das erzeugte Artefakt <code>Topology</code> ist zentraler Bestandteil der übergeordneten System Description und bildet die Basis für nachgelagerte Schritte wie Signal-Routing und Kommunikationsextrakt-Erstellung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-829b02bf32720d30", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Aktivitätsdiagramm (Methodology Activity) im Kontext der AUTOSAR-Systemkonfiguration (Methodology). Das Diagramm spezifiziert die Aktivität „Define System Topology“ innerhalb der Entwurfsphase für die Systemtopologie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Kardinalität <code>1</code>): Ausführende Instanz (<code>«performs»</code>).\n</li></ul>\n</li><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Define System Topology</code>: Zentrale Methodik-Aktivität (dargestellt als Prozessbaustein/Aktivitäts-Symbol).\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>ECU Resources Description</code> (Kardinalität <code>1..*</code>): Eingangsartefakt mit Stereotyp <code>«input»</code>.\n</li><li><code>Topology</code> (Kardinalität <code>1</code>): Ausgangsartefakt mit Stereotyp <code>«output»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>System Engineer</code> initiiert und führt die Aktivität <code>Define System Topology</code> aus.\n</li><li>Als Eingabe werden mindestens eine oder mehrere Instanzen von <code>ECU Resources Description</code> (<code>1..*</code>) konsumiert.\n</li><li>Die Aktivität erzeugt als Ergebnis genau eine Systemtopologie-Beschreibung (<code>Topology</code>, Kardinalität <code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Definition der Systemtopologie setzt das Vorliegen der ECU-Ressourcenbeschreibungen voraus, um Netzwerkcluster, Steuergeräte und Busverbindungen festzulegen. Das erzeugte Artefakt <code>Topology</code> ist zentraler Bestandteil der übergeordneten System Description und bildet die Basis für nachgelagerte Schritte wie Signal-Routing und Kommunikationsextrakt-Erstellung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-97f64894e144650e", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Aktivitätsdiagramm (Methodology Activity) im Kontext der AUTOSAR-Systemkonfiguration (Methodology). Das Diagramm spezifiziert die Aktivität „Define System Topology“ innerhalb der Entwurfsphase für die Systemtopologie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Kardinalität <code>1</code>): Ausführende Instanz (<code>«performs»</code>).\n</li></ul>\n</li><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Define System Topology</code>: Zentrale Methodik-Aktivität (dargestellt als Prozessbaustein/Aktivitäts-Symbol).\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>ECU Resources Description</code> (Kardinalität <code>1..*</code>): Eingangsartefakt mit Stereotyp <code>«input»</code>.\n</li><li><code>Topology</code> (Kardinalität <code>1</code>): Ausgangsartefakt mit Stereotyp <code>«output»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>System Engineer</code> initiiert und führt die Aktivität <code>Define System Topology</code> aus.\n</li><li>Als Eingabe werden mindestens eine oder mehrere Instanzen von <code>ECU Resources Description</code> (<code>1..*</code>) konsumiert.\n</li><li>Die Aktivität erzeugt als Ergebnis genau eine Systemtopologie-Beschreibung (<code>Topology</code>, Kardinalität <code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Definition der Systemtopologie setzt das Vorliegen der ECU-Ressourcenbeschreibungen voraus, um Netzwerkcluster, Steuergeräte und Busverbindungen festzulegen. Das erzeugte Artefakt <code>Topology</code> ist zentraler Bestandteil der übergeordneten System Description und bildet die Basis für nachgelagerte Schritte wie Signal-Routing und Kommunikationsextrakt-Erstellung.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ac6a64e782d9cd2d", "to": "FIG-829b02bf32720d30", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-829b02bf32720d30", "to": "FIG-97f64894e144650e", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
